create table if not exists public.hot_seat_break_polls (id uuid primary key default gen_random_uuid(),title text not null,question text not null,options jsonb not null default '[]'::jsonb,enabled boolean not null default true,starts_at timestamptz not null default now(),ends_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null default auth.uid());
create table if not exists public.hot_seat_break_poll_votes (id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.hot_seat_break_polls(id) on delete cascade,user_id uuid not null,option_index integer not null,created_at timestamptz not null default now(),unique(poll_id,user_id));
alter table public.hot_seat_break_polls enable row level security; alter table public.hot_seat_break_poll_votes enable row level security;
revoke all on public.hot_seat_break_polls,public.hot_seat_break_poll_votes from anon,authenticated; grant select on public.hot_seat_break_polls to authenticated;
drop policy if exists "hotseat poll read" on public.hot_seat_break_polls; create policy "hotseat poll read" on public.hot_seat_break_polls for select to authenticated using(enabled=true);
